<template>
	<!-- Lembar kalender satu tanggal. Mengikuti pola kalender rentang di Tts.vue,
	     tetapi memilih satu hari langsung menerapkannya. -->
	<Teleport to="body">
		<Transition
			enter-active-class="transition-opacity duration-200"
			enter-from-class="opacity-0"
			leave-active-class="transition-opacity duration-150"
			leave-to-class="opacity-0"
		>
			<div
				v-if="open"
				class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40"
				@click.self="emit('update:open', false)"
			>
				<Transition
					appear
					enter-active-class="transition-transform duration-200 ease-out"
					enter-from-class="translate-y-full"
					leave-active-class="transition-transform duration-150 ease-in"
					leave-to-class="translate-y-full"
				>
					<div
						v-if="open"
						class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
					>
						<div class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300" />
						<h2 class="text-center text-base font-semibold text-ui-ink-gray-900">
							{{ judul }}
						</h2>

						<!-- Navigasi bulan -->
						<div class="mb-2 mt-3 flex items-center justify-between px-1">
							<button
								type="button"
								class="flex h-9 w-9 items-center justify-center rounded-full text-ui-ink-gray-600 hover:bg-ui-surface-gray-100 disabled:opacity-30"
								aria-label="Bulan sebelumnya"
								:disabled="!bolehMundur"
								@click="geserBulan(-1)"
							>
								<svg
									xmlns="http://www.w3.org/2000/svg"
									viewBox="0 0 24 24"
									class="h-5 w-5"
									fill="none"
									stroke="currentColor"
									stroke-width="2"
									stroke-linecap="round"
									stroke-linejoin="round"
								>
									<path d="m15 18-6-6 6-6" />
								</svg>
							</button>
							<span class="text-sm font-semibold text-ui-ink-gray-900">{{
								labelBulan
							}}</span>
							<button
								type="button"
								class="flex h-9 w-9 items-center justify-center rounded-full text-ui-ink-gray-600 hover:bg-ui-surface-gray-100 disabled:opacity-30"
								aria-label="Bulan berikutnya"
								:disabled="!bolehMaju"
								@click="geserBulan(1)"
							>
								<svg
									xmlns="http://www.w3.org/2000/svg"
									viewBox="0 0 24 24"
									class="h-5 w-5"
									fill="none"
									stroke="currentColor"
									stroke-width="2"
									stroke-linecap="round"
									stroke-linejoin="round"
								>
									<path d="m9 18 6-6-6-6" />
								</svg>
							</button>
						</div>

						<!-- Grid kalender, pekan mulai Senin -->
						<div class="grid grid-cols-7 gap-y-1 text-center">
							<div
								v-for="w in HARI"
								:key="w"
								class="py-1.5 text-xs font-semibold text-ui-ink-gray-400"
							>
								{{ w }}
							</div>
							<div v-for="(sel, i) in selHari" :key="i" class="py-0.5">
								<button
									v-if="sel"
									type="button"
									class="mx-auto flex h-9 w-9 items-center justify-center rounded-full text-sm transition disabled:opacity-25"
									:class="kelasHari(sel)"
									:disabled="!bolehDipilih(sel)"
									@click="pilih(sel)"
								>
									{{ Number(sel.slice(8)) }}
								</button>
							</div>
						</div>

						<div class="mt-5 flex items-center gap-3">
							<button
								type="button"
								class="w-full rounded-full border border-ui-line-gray-300 py-3 text-sm font-semibold text-ui-ink-gray-700 transition active:scale-[0.98]"
								@click="pilih('')"
							>
								Semua tanggal
							</button>
							<button
								type="button"
								class="w-full rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.98]"
								@click="emit('update:open', false)"
							>
								Tutup
							</button>
						</div>
					</div>
				</Transition>
			</div>
		</Transition>
	</Teleport>
</template>

<script setup>
import { computed, ref, watch } from 'vue'

const props = defineProps({
	open: { type: Boolean, default: false },
	modelValue: { type: String, default: '' }, // 'YYYY-MM-DD' atau ''
	min: { type: String, default: '' },
	max: { type: String, default: '' },
	judul: { type: String, default: 'Pilih tanggal' },
})
const emit = defineEmits(['update:open', 'update:modelValue', 'change'])

const HARI = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const BULAN = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]

// Format lokal 'YYYY-MM-DD' — toISOString bisa menggeser tanggal di zona WIB.
function ymd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const h = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${h}`
}
function awalBulan(s) {
	const [y, m] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, 1)
}

// Bulan yang ditampilkan (tanggal 1).
const kursor = ref(new Date())

// Tiap kali dibuka, mulai dari tanggal terpilih, atau hari ini bila masih dalam
// batas, atau batas akhirnya.
watch(
	() => props.open,
	(buka) => {
		if (!buka) return
		let dasar = props.modelValue || ymd(new Date())
		if (props.max && dasar > props.max) dasar = props.max
		if (props.min && dasar < props.min) dasar = props.min
		kursor.value = awalBulan(dasar)
	}
)

const labelBulan = computed(
	() => `${BULAN[kursor.value.getMonth()]} ${kursor.value.getFullYear()}`
)

const selHari = computed(() => {
	const y = kursor.value.getFullYear()
	const m = kursor.value.getMonth()
	const offset = (new Date(y, m, 1).getDay() + 6) % 7 // Senin = 0
	const jumlah = new Date(y, m + 1, 0).getDate()
	const sel = Array(offset).fill(null)
	for (let d = 1; d <= jumlah; d++) sel.push(ymd(new Date(y, m, d)))
	return sel
})

const bolehMundur = computed(() => !props.min || ymd(kursor.value) > props.min)
const bolehMaju = computed(() => {
	if (!props.max) return true
	const akhir = new Date(kursor.value.getFullYear(), kursor.value.getMonth() + 1, 0)
	return ymd(akhir) < props.max
})

function geserBulan(arah) {
	kursor.value = new Date(kursor.value.getFullYear(), kursor.value.getMonth() + arah, 1)
}

function bolehDipilih(s) {
	return (!props.min || s >= props.min) && (!props.max || s <= props.max)
}

function kelasHari(s) {
	if (s === props.modelValue) return 'bg-primary font-semibold text-ui-onPrimary'
	if (s === ymd(new Date())) return 'font-semibold text-primary'
	return 'text-ui-ink-gray-700 hover:bg-ui-surface-gray-100'
}

function pilih(s) {
	emit('update:modelValue', s)
	emit('change', s)
	emit('update:open', false)
}
</script>
